def forward(groups):
    values = []
    for g in groups:
        if g == '****':
            values.append(None)
        else:
            values.append(int(g))
    if len(values) != 6:
        raise ValueError("Expected 6 fan speed values, got: {}".format(len(values)))
    return {'stored': values, 'layout': []}

def inverse(record):
    values = record['stored']
    return '(' + ' '.join(str(v) if v is not None else '****' for v in values) + ')'
